import React from 'react';

const Header = () => {
  return (
    <header style={{
      position: 'sticky',
      top: 0,
      zIndex: 100,
      background: 'rgba(10, 17, 40, 0.65)',
      backdropFilter: 'blur(12px)',
      WebkitBackdropFilter: 'blur(12px)',
      border: '1px solid rgba(255, 255, 255, 0.1)',
      padding: '16px 60px',
      transition: 'all 0.3s ease',
    }}>
      <div style={{
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        maxWidth: '1400px',
        margin: '0 auto',
      }}>
        {/* Logo */}
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px', cursor: 'pointer' }}>
          <svg width="32" height="32" viewBox="0 0 48 48" fill="none" xmlns="http://www.w3.org/2000/svg">
            <circle cx="24" cy="24" r="22" stroke="currentColor" strokeWidth="1.5" opacity="0.6" style={{ color: 'var(--accent-gold)' }} />
            <path d="M24 10L35 18V30C35 36 24 42 24 42S13 36 13 30V18L24 10Z" stroke="currentColor" strokeWidth="2" fill="none" strokeLinecap="round" strokeLinejoin="round" style={{ color: 'var(--accent-gold)' }} />
            <line x1="18" y1="30" x2="24" y2="36" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" style={{ color: 'var(--accent-gold)' }} />
            <line x1="30" y1="30" x2="24" y2="36" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" style={{ color: 'var(--accent-gold)' }} />
          </svg>
          <h1 style={{
            color: 'var(--accent-gold)',
            fontSize: '24px',
            fontWeight: '800',
            margin: 0,
            letterSpacing: '-0.5px',
          }}>
            Artemis
          </h1>
        </div>

        {/* Navigation */}
        <nav style={{ display: 'flex', gap: '40px', alignItems: 'center' }}>
          <a
            href="/"
            style={{
              color: 'rgba(255, 255, 255, 0.85)',
              textDecoration: 'none',
              fontWeight: '500',
              fontSize: '15px',
              letterSpacing: '0.3px',
              position: 'relative',
              transition: 'color 0.3s ease',
              paddingBottom: '4px',
              borderBottom: '2px solid transparent',
              borderBottomColor: 'transparent',
            }}
            onMouseEnter={(e) => {
              e.target.style.color = 'var(--accent-gold)';
              e.target.style.borderBottomColor = 'var(--accent-gold)';
            }}
            onMouseLeave={(e) => {
              e.target.style.color = 'rgba(255, 255, 255, 0.85)';
              e.target.style.borderBottomColor = 'transparent';
            }}
          >
            Home
          </a>
        </nav>
      </div>
    </header>
  );
};

export default Header;
